public class DatasetUtilities_iterateRangeBounds_TriageGen0Test {

    @Test
    public void testIterateRangeBounds_StandardXYDataset_IncludeIntervalFalse() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(2);
        when(dataset.getYValue(0, 0)).thenReturn(10.0);
        when(dataset.getYValue(0, 1)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, false);

        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(20.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateRangeBounds_StandardXYDataset_IncludeIntervalTrue() {
        // Even if true, if it's not IntervalXYDataset or OHLCDataset, it falls to standard case
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getYValue(0, 0)).thenReturn(5.0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, true);

        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(5.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateRangeBounds_IntervalXYDataset_IncludeIntervalTrue() {
        IntervalXYDataset dataset = Mockito.mock(IntervalXYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(2);

        // Item 0: [1.0, 5.0]
        when(dataset.getStartYValue(0, 0)).thenReturn(1.0);
        when(dataset.getEndYValue(0, 0)).thenReturn(5.0);
        // Item 1: [NaN, 10.0]
        when(dataset.getStartYValue(0, 1)).thenReturn(Double.NaN);
        when(dataset.getEndYValue(0, 1)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, true);

        assertEquals(1.0, result.getLower(), 1e-9);
        assertEquals(10.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateRangeBounds_OHLCDataset_IncludeIntervalTrue() {
        OHLCDataset dataset = Mockito.mock(OHLCDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);

        // Low: 2.0, High: 8.0
        when(dataset.getLowValue(0, 0)).thenReturn(2.0);
        when(dataset.getHighValue(0, 0)).thenReturn(8.0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, true);

        assertEquals(2.0, result.getLower(), 1e-9);
        assertEquals(8.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateRangeBounds_EmptyDataset_ReturnsNull() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, false);

        assertNull(result);
    }

    @Test
    public void testIterateRangeBounds_AllNaNValues_ReturnsNull() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getYValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, false);

        assertNull(result);
    }

    @Test
    public void testIterateRangeBounds_IntervalXYDataset_AllNaN_ReturnsNull() {
        IntervalXYDataset dataset = Mockito.mock(IntervalXYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getStartYValue(0, 0)).thenReturn(Double.NaN);
        when(dataset.getEndYValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, true);

        assertNull(result);
    }

    @Test
    public void testIterateRangeBounds_OHLCDataset_AllNaN_ReturnsNull() {
        OHLCDataset dataset = Mockito.mock(OHLCDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getLowValue(0, 0)).thenReturn(Double.NaN);
        when(dataset.getHighValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, true);

        assertNull(result);
    }

    @Test
    public void testIterateRangeBounds_StandardXYDataset_WithNaN_IgnoresNaN() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(3);
        when(dataset.getYValue(0, 0)).thenReturn(Double.NaN);
        when(dataset.getYValue(0, 1)).thenReturn(5.0);
        when(dataset.getYValue(0, 2)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, false);

        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(15.0, result.getUpper(), 1e-9);
    }
}
